57	// A10：跨命名空间 round-trip —— workflow 生成的锁 id 能被 dispatcher
58	// ParseRouteEdge/IsTrafficBlockOwner 正确解析，反之亦然（两侧必须收敛到同一实现）
59	TEST(TrafficReservationTest, CrossNamespaceRouteLockRoundTrip) {
60	  namespace dispatcher = amr_dispatcher_core::dispatcher;
61	
62	  // workflow 生成 -> dispatcher 解析
63	  const auto parsed_by_dispatcher =
64	      dispatcher::ResourceTable::ParseRouteEdge(RouteLockId("storage_b", "packing"));
65	  ASSERT_TRUE(parsed_by_dispatcher.has_value());
66	  EXPECT_EQ(parsed_by_dispatcher->first, "packing");
67	  EXPECT_EQ(parsed_by_dispatcher->second, "storage_b");
68	  EXPECT_TRUE(
69	      dispatcher::ResourceTable::IsTrafficBlockOwner(TrafficBlockOwnerId("maintenance")));
70	  EXPECT_FALSE(dispatcher::ResourceTable::IsTrafficBlockOwner("mission_a"));
71	
72	  // dispatcher 生成 -> workflow 解析
73	  const auto parsed_by_workflow =
74	      ParseRouteLock(dispatcher::ResourceTable::RouteEdgeId("storage_b", "packing"));
75	  ASSERT_TRUE(parsed_by_workflow.has_value());
76	  EXPECT_EQ(parsed_by_workflow->first, "packing");
77	  EXPECT_EQ(parsed_by_workflow->second, "storage_b");
78	  EXPECT_TRUE(IsTrafficBlockOwner(TrafficBlockOwnerId("maintenance")));
79	
80	  // 节点锁 id 与整条路径锁 id 集两侧逐项一致
81	  EXPECT_EQ(RouteNodeLockId("storage_a"), dispatcher::ResourceTable::RouteNodeId("storage_a"));
82	  EXPECT_EQ(BuildRouteLockIds({"receiving", "storage_a", "packing"}, true),
83	            dispatcher::ResourceTable::BuildLockIds({"receiving", "storage_a", "packing"}, true));
84	  EXPECT_EQ(BuildRouteLockIds({"receiving", "storage_a"}, false),
85	            dispatcher::ResourceTable::BuildLockIds({"receiving", "storage_a"}, false));
86	}
