199	TEST(TrafficReservationTest, PlanTrafficDeadlockDetection_IgnoresTrafficBlocksAndNodes) {
200	  RouteLockMap route_locks{
201	      {"route_edge:receiving__storage_a", "mission_a"},
202	      {"route_node:storage_a", "mission_b"},
203	      {"route_edge:packing__storage_a", "traffic_block:maintenance"},
