12	// 时空预约区间：[start_time, end_time]
13	struct TimeInterval {
14	  std::chrono::steady_clock::time_point start;
15	  std::chrono::steady_clock::time_point end;
16	
17	  bool OverlapsWith(const TimeInterval& other) const {
18	    return start < other.end && other.start < end;
19	  }
20	};
21	
22	struct TimeSpaceReservation {
23	  std::string mission_id;
24	  std::string resource_id;
25	  TimeInterval interval;
26	};
27	
28	// 资源预留表：兼具静态原子锁与时空预约区间锁（Time-Space Reservation）
29	class ResourceTable {
30	 public:
31	  struct ReserveResult {
32	    bool success = false;
