      });

  RCLCPP_INFO(get_logger(),
              "DispatcherNode configured (capacity=%zu, comparator=%s, navigation_backend=%s)",
              cap, comp_name.c_str(), navigation_backend_.c_str());
  return CallbackReturn::SUCCESS;
}

