1	#include "amr_dispatcher_ros/dispatcher_node.hpp"
2	
3	#include <algorithm>
4	#include <chrono>
5	#include <cmath>
6	#include <unordered_set>
7	#include <utility>
8	#include <vector>
9	
10	#include "amr_dispatcher_core/dispatcher/topology_projection.hpp"
11	#include "amr_dispatcher_core/workflow/traffic_planning.hpp"
12	#include "amr_dispatcher_ros/mission_identity.hpp"
13	
14	using namespace std::chrono_literals;
15	
16	namespace amr_dispatcher_ros {
17	
18	DispatcherNode::DispatcherNode(const rclcpp::NodeOptions& options)
19	    : rclcpp_lifecycle::LifecycleNode("dispatcher_node", options) {
20	  declare_parameter("queue_capacity", 128);
21	  declare_parameter("comparator", "priority_fifo");
22	  declare_parameter("schedule_rate_hz", 10.0);
23	  declare_parameter("deadlock_check_rate_hz", 1.0);
24	  declare_parameter("max_active_missions", 4);
25	  declare_parameter("stations_file", "config/stations.yaml");
26	  declare_parameter("path_step_size_m", 0.1);
27	  declare_parameter("recovery_dock_station", "station_charge_1");
28	  declare_parameter("navigation_backend", "plan");
29	  recovery_dock_station_ = get_parameter("recovery_dock_station").as_string();
30	}
31	
32	DispatcherNode::~DispatcherNode() = default;
33	
34	CallbackReturn DispatcherNode::on_configure(const rclcpp_lifecycle::State& /*state*/) {
35	  const std::size_t cap = get_parameter("queue_capacity").as_int();
36	  const std::string comp_name = get_parameter("comparator").as_string();
37	
38	  queue_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionQueue>(
39	      amr_dispatcher_core::dispatcher::MissionQueue::Config{cap, comp_name});
40	  reservation_table_ = std::make_unique<amr_dispatcher_core::dispatcher::TrafficReservationTable>();
41	  event_log_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionEventLog>(256);
42	  deadlock_detector_ = std::make_unique<amr_dispatcher_core::dispatcher::DeadlockDetector>(
43	      amr_dispatcher_core::dispatcher::DeadlockDetectorConfig{
44	          static_cast<std::size_t>(get_parameter("max_active_missions").as_int()),
45	          10s, 30s});
46	  recovery_policy_ = std::make_unique<amr_dispatcher_core::dispatcher::RecoveryPolicy>();
47	
48	  // 站点目录与基准线性规划器：任务激活时把 pickup→dropoff 展开成 /plan 下发。
49	  // 目录经 StationCatalogReloader 持有：构造时加载，mtime 变化自动热重载；
50	  // 初始加载失败也照常挂监听，文件补齐后下一个 Tick 即生效。
51	  const std::string stations_file = get_parameter("stations_file").as_string();
52	  catalog_reloader_ =
53	      std::make_unique<amr_dispatcher_core::catalog::StationCatalogReloader>(stations_file);
54	  if (catalog_reloader_->loaded()) {
55	    RCLCPP_INFO(get_logger(), "Loaded %zu stations from %s",
56	                catalog_reloader_->catalog().stations.size(), stations_file.c_str());
57	  } else {
58	    RCLCPP_WARN(get_logger(),
59	                "Failed to load stations file %s; planning disabled until hot reload succeeds",
60	                stations_file.c_str());
61	  }
62	  planner_ = std::make_unique<amr_dispatcher_core::MockLinearPlanner>(
63	      get_parameter("path_step_size_m").as_double());
64	
65	  state_pub_ = create_publisher<amr_dispatcher_interfaces::msg::DispatcherState>(
66	      "/dispatcher/state", 10);
67	  event_pub_ = create_publisher<amr_dispatcher_interfaces::msg::MissionEvent>(
68	      "/dispatcher/events", 20);
69	  plan_pub_ = create_publisher<nav_msgs::msg::Path>("/plan", 1);
70	  // 拓扑状态：safety_gate（deadlock_active_）与 visualizer（绿锁边/红警戒柱）的死锁输入
71	  topology_pub_ = create_publisher<amr_dispatcher_interfaces::msg::TopologyState>(
72	      "/dispatcher/topology_state", 10);
73	
74	  // 位姿与到达信号订阅：path_tracker 的 TrackingError.arrived 驱动任务完成
75	  odom_sub_ = create_subscription<nav_msgs::msg::Odometry>(
76	      "/odom", 10, std::bind(&DispatcherNode::OdomCb, this, std::placeholders::_1));
